          }
        },
        "parameters": {}
      }
    ],
    "goal_map": {
      "goal_prepare_ch2o": {
        "port": "prepared_geometry",
        "evidence": {
          "producer_step_id": "prepare_ch2o"
        }
      },
      "goal_pol_original": {
        "port": "static_dipole_dipole_polarizability_tensor",
        "gap": "No producer yet: a concrete RHF/def2-SVP static-polarizability input can only be authored after the qualified prepared geometry exists as a real artifact; it must then be run independently through managed ORCA."
      },
      "goal_rotation_relation": {
        "port": "rotation_relation",
        "gap": "The rotation convention (origin (0,0,0), axis (1,2,3) normalized, right-hand rule, +37 degrees, atom order and internal geometry preserved) can be recorded numerically, but the rotated XYZ and its numerical relation require the prepared geometry first."
      },
      "goal_pol_rotated": {
        "port": "static_dipole_dipole_polarizability_tensor_rotated",
        "gap": "No independent rotated-geometry calculation yet: the rotated XYZ must be generated from the prepared geometry, archived, and then used in a separate managed ORCA run with identical scientific settings; the rotated tensor may not be obtained by transforming the first tensor."
      },
      "goal_deliver_results": {
        "port": "delivery_bundle",
        "gap": "Depends on both archived independent ORCA calculations, the two delivered XYZ files, and the derived comparison table with >=7 decimals for tensors and >=5 for isotropic values."
      },
      "goal_verify_tensors": {
        "port": "tensor_transformation_verification",
        "gap": "Transformation checks (component-level comparison under the rotation matrix vs. invariance of the isotropic value) require both real 3x3 tensors from actual ORCA outputs."
      },
      "goal_preserve_artifacts": {
        "port": "artifact_preservation",
        "gap": "Artifacts (generation/analysis scripts, both XYZ files, input files, stdout/stderr, data tables, limitations) will be archived as each writer and calculation step is executed."
      },
      "goal_seed_1701": {
        "port": "random_seed_record",
        "gap": "No random-number-using calculation has been authored yet; seed 1701 policy will be recorded, and any library/model that cannot fix the seed will be explicitly marked as not fixable without fabricating determinism."
      }
    }
  },
  "reason": "Correcting the single rejected binding: structure.prepare's input role 'identity' must bind the producer's actual output port 'resolved_identity' (not the resolve step's input role name). The rest is retained: first establish the mandatory identity anchor (resolve) and the qualified initial geometry (prepare) for system_ch2o, since the native-input contract forbids substituting a task-generated XYZ for the initial identity anchor. After the prepare receipt is inspected, I will write the original and actively rotated XYZ files, compose and execute two matching RHF/def2-SVP static-polarizability ORCA inputs independently, then add table/verification/rotation-record steps from real receipts."
}
